function validate(input) {
  const [{ Employee = [] }] = input;
  const ids = new Set();
  for (const [id, , , managerId] of Employee) {
    if (id === null) return 'Every employee needs an id.';
    if (ids.has(id)) return `id ${id} appears twice in Employee.`;
    if (managerId === id) return `Employee ${id} cannot manage themselves.`;
    ids.add(id);
  }
  return null;
}

generator:
function generate(rand, size) {
  const names = ['John', 'Dan', 'James', 'Amy', 'Anne', 'Ron', 'Sam', 'Ana'];
  const departments = ['A', 'B', 'C'];
  const pick = list => list[Math.floor(rand() * list.length)];
  const small = size === 'small';
  const count = small ? Math.floor(rand() * 9) : 2000;
  // Small tables pile reports onto ids 1 and 2 so counts near 5 are common; id 9 is a manager with no row.
  const bosses = small ? [null, 1, 1, 1, 2, 2, 9] : null;
  const Employee = [];
  for (let id = 1; id <= count; id++) {
    let managerId;
    if (small) managerId = pick(bosses);
    else managerId = rand() < 0.05 ? null : rand() < 0.1 ? 2001 + Math.floor(rand() * 20) : 1 + Math.floor(rand() * 400);
    if (managerId === id) managerId = null;
    Employee.push([id, small ? pick(names) : `Emp${id % 700}`, pick(departments), managerId]);
  }
  return [{ Employee }];
}
